VF=["Verdadeiro","Falso"]
F2=[
# ---------------- Empuxo e princípio de Arquimedes (em) ----------------
("em","O princípio de Arquimedes afirma que um corpo mergulhado em um fluido recebe uma força para cima cujo valor é igual:",["Ao peso do fluido que o corpo desloca.","Ao peso do próprio corpo.","À massa do corpo multiplicada pela área.","À pressão atmosférica local."],0,"Pense no fluido que sai do lugar quando o corpo entra.","O empuxo tem o mesmo valor do peso do volume de fluido deslocado pelo corpo.",{"f":"empuxo"}),
("em","Qual é a direção e o sentido do empuxo?",["Vertical, para cima.","Vertical, para baixo.","Horizontal, para a direita.","Sempre na direção do movimento do corpo."],0,"É a força que ajuda o corpo a boiar.","O empuxo é vertical e aponta para cima, contrário ao peso.",{"f":"empuxo"}),
("em","Verdadeiro ou falso: o empuxo depende da massa específica do fluido e do volume do corpo que está imerso.",VF,0,"Use E = μ do fluido · g · volume imerso.","E = μf·g·Vi. Quanto mais denso o fluido e maior o volume imerso, maior é o empuxo.",{"v":1}),
("em","Um corpo maciço afunda em um líquido quando:",["Sua densidade é maior que a do líquido.","Sua densidade é menor que a do líquido.","Seu volume é muito grande.","O líquido é muito frio."],0,"Compare o peso com o empuxo máximo.","Se a densidade do corpo é maior que a do líquido, o peso supera o empuxo máximo e o corpo afunda.",{}),
("em","Um barco flutua em equilíbrio, parcialmente imerso. Nessa situação:",["O empuxo tem o mesmo valor do peso do barco.","O empuxo é maior que o peso.","O empuxo é nulo.","O peso do barco é nulo."],0,"Em equilíbrio, a força resultante é nula.","Para o barco ficar parado na vertical, o empuxo e o peso têm o mesmo valor e sentidos opostos.",{"f":"empuxo"}),
("em","Por que uma pessoa se sente mais leve dentro de uma piscina?",["Porque a água exerce sobre ela uma força para cima, o empuxo.","Porque a massa da pessoa diminui.","Porque a gravidade é menor na água.","Porque a pressão atmosférica some."],0,"O peso real não muda, mas há outra força agindo.","A massa e o peso continuam os mesmos. O empuxo equilibra parte do peso, e por isso o corpo parece mais leve.",{}),
("em","Verdadeiro ou falso: dois objetos de mesmo volume, totalmente imersos na água, sofrem o mesmo empuxo, mesmo que tenham massas diferentes.",VF,0,"O empuxo depende do volume deslocado, não da massa do corpo.","O volume de água deslocado é igual nos dois casos, então o empuxo também é igual.",{"v":1}),
("em","Como um submarino consegue subir à superfície?",["Esvaziando os tanques de lastro, o que reduz seu peso médio.","Aumentando a pressão atmosférica.","Ligando as hélices na vertical, sem alterar nada mais.","Aumentando a quantidade de água nos tanques."],0,"Pense em como mudar a densidade média do submarino.","Ao expulsar a água dos tanques, o submarino fica menos denso e o empuxo passa a superar o peso.",{}),
("em","Por que é mais fácil boiar no Mar Morto do que em uma piscina comum?",["Porque a água do Mar Morto é mais densa e produz mais empuxo.","Porque a água do Mar Morto é menos densa.","Porque lá a gravidade é maior.","Porque lá não há pressão atmosférica."],0,"Compare as massas específicas das duas águas.","A água salgada do Mar Morto é muito mais densa. Para o mesmo volume imerso, o empuxo é maior.",{}),
("em","Verdadeiro ou falso: o empuxo também atua em corpos mergulhados em gases, como um balão no ar.",VF,0,"Gases também são fluidos.","O princípio de Arquimedes vale para qualquer fluido, inclusive o ar. Por isso balões cheios de gás menos denso que o ar sobem.",{"v":1}),
("em","Por que o gelo flutua na água, com a maior parte do volume submersa?",["Porque o gelo é um pouco menos denso que a água líquida.","Porque o gelo não tem peso.","Porque o gelo é muito mais denso que a água.","Porque o gelo é oco."],0,"A massa específica do gelo é cerca de 0,92 g/cm³.","Como a massa específica do gelo (cerca de 0,92 g/cm³) é menor que a da água, ele flutua, com cerca de 90% do volume submerso.",{}),
("em","Um bloco tem peso de 50 N no ar. Mergulhado na água, uma balança indica 30 N. Qual é o valor do empuxo sobre o bloco?",["20 N","80 N","30 N","50 N"],0,"Peso aparente = peso real menos empuxo.","P_aparente = P − E, então E = 50 − 30 = 20 N.",{"c":1}),
("em","Um bloco de 0,002 m³ está totalmente imerso na água (μ = 1000 kg/m³, g = 10 m/s²). Qual é o empuxo sobre ele?",["20 N","2 N","200 N","0,2 N"],0,"Use E = μ·g·V.","E = 1000 × 10 × 0,002 = 20 N.",{"c":1}),
("em","Um corpo homogêneo flutua na água com 40% do seu volume imerso. Qual é a massa específica do corpo? (μ da água = 1000 kg/m³)",["400 kg/m³","600 kg/m³","1000 kg/m³","250 kg/m³"],0,"Em equilíbrio, peso = empuxo.","μc·V·g = μágua·(0,4V)·g, então μc = 0,4 × 1000 = 400 kg/m³.",{"c":1}),
# ---------------- Princípio de Pascal e prensa hidráulica (pp) ----------------
("pp","O princípio de Pascal afirma que, em um líquido em equilíbrio, um acréscimo de pressão em um ponto:",["Transmite-se integralmente a todos os pontos do líquido.","Fica apenas no ponto em que foi aplicado.","Diminui com a distância.","Só chega até o fundo do recipiente."],0,"Pense em apertar uma seringa fechada.","O acréscimo de pressão se transmite com o mesmo valor a todos os pontos do líquido e às paredes do recipiente.",{"f":"prensa"}),
("pp","Qual é a relação entre as forças e as áreas dos êmbolos de uma prensa hidráulica ideal?",["F₁ / A₁ = F₂ / A₂","F₁ · A₁ = F₂ · A₂","F₁ + A₁ = F₂ + A₂","F₁ = F₂, sempre."],0,"A pressão é a mesma nos dois êmbolos.","Como a pressão é transmitida integralmente, F₁/A₁ = F₂/A₂.",{"f":"prensa"}),
("pp","Por que uma prensa hidráulica consegue multiplicar uma força?",["Porque a pressão é igual nos dois êmbolos e o êmbolo maior tem mais área.","Porque o líquido cria energia.","Porque o êmbolo maior é mais pesado.","Porque a pressão é maior no êmbolo maior."],0,"Com p igual, F = p · A.","Com a mesma pressão, a força é proporcional à área. No êmbolo maior, a força é maior.",{"f":"prensa"}),
("pp","Verdadeiro ou falso: uma prensa hidráulica ideal multiplica também a energia (o trabalho) realizada.",VF,1,"Pense no deslocamento do êmbolo menor.","A força é multiplicada, mas o êmbolo menor se desloca mais. O trabalho é o mesmo (em um sistema ideal).",{"v":1}),
("pp","Qual destes equipamentos usa o princípio de Pascal?",["O freio hidráulico de um carro.","O termômetro de mercúrio.","A lâmpada incandescente.","O barômetro de Torricelli."],0,"Pense em transmitir força por meio de um líquido.","Nos freios hidráulicos, a pressão aplicada no pedal é transmitida pelo fluido até as rodas.",{}),
("pp","Por que as prensas hidráulicas usam líquidos, e não gases?",["Porque os líquidos são praticamente incompressíveis e transmitem bem a pressão.","Porque os líquidos não têm massa.","Porque os gases são mais pesados.","Porque os gases nunca transmitem pressão."],0,"Pense no que ocorre quando você comprime ar e quando comprime água.","O líquido quase não muda de volume, então a pressão se transmite de forma eficiente.",{}),
("pp","Se a força aplicada no êmbolo menor de uma prensa for dobrada, a força no êmbolo maior:",["Também dobra.","Fica pela metade.","Não muda.","Quadruplica."],0,"F₂ = F₁ · A₂ / A₁ é proporcional a F₁.","As áreas continuam as mesmas. Dobrando F₁, dobra F₂.",{}),
("pp","O êmbolo maior de uma prensa tem área 10 vezes a do êmbolo menor. A força no êmbolo maior é:",["10 vezes a força no menor.","10 vezes menor.","Igual.","100 vezes maior."],0,"F₂/F₁ = A₂/A₁.","F₂ = F₁ · (A₂/A₁) = 10 F₁.",{}),
("pp","Em uma prensa hidráulica, as áreas dos êmbolos são 0,01 m² e 0,5 m². Uma força de 100 N no êmbolo menor equilibra qual força no maior?",["5000 N","2 N","50 N","500 N"],0,"F₂ = F₁ · A₂ / A₁.","F₂ = 100 × 0,5 / 0,01 = 5000 N.",{"c":1}),
("pp","Um macaco hidráulico tem êmbolos de 2 cm² e 40 cm². Qual força mínima no êmbolo menor levanta um carro de peso 8000 N?",["400 N","160 N","4000 N","8000 N"],0,"F₁ = F₂ · A₁ / A₂.","F₁ = 8000 × 2 / 40 = 400 N.",{"c":1}),
("pp","Em uma prensa, o êmbolo maior tem área 10 vezes a do menor. Se o êmbolo menor desce 20 cm, quanto sobe o maior?",["2 cm","200 cm","20 cm","10 cm"],0,"O volume de líquido que sai de um lado entra no outro.","A₁·d₁ = A₂·d₂, então d₂ = 20 / 10 = 2 cm.",{"c":1}),
# ---------------- reforço das áreas anteriores ----------------
("de","Verdadeiro ou falso: a massa específica da água é de aproximadamente 1 g/cm³.",VF,0,"Lembre da conversão para 1000 kg/m³.","1 g/cm³ equivale a 1000 kg/m³, valor usado para a água.",{"v":1}),
("de","O que acontece com a massa específica de um líquido quando ele é aquecido e se dilata (sem perder massa)?",["Ela diminui.","Ela aumenta.","Fica igual.","Torna-se nula."],0,"μ = m/V; o que mudou em V?","A massa fica igual e o volume aumenta, então a razão m/V diminui.",{}),
("de","Um cubo maciço de aresta 10 cm tem massa de 2,7 kg. Qual é a massa específica do material, em g/cm³?",["2,7 g/cm³","27 g/cm³","0,27 g/cm³","2700 g/cm³"],0,"V = 10 × 10 × 10 cm³ e m = 2700 g.","V = 1000 cm³ e m = 2700 g, então μ = 2700 / 1000 = 2,7 g/cm³.",{"c":1}),
("de","Duas esferas têm a mesma massa, mas a esfera A tem o dobro do volume da esfera B. Qual afirmação é correta?",["A massa específica de A é a metade da de B.","A massa específica de A é o dobro da de B.","As massas específicas são iguais.","A esfera A é sempre mais pesada."],0,"μ = m/V com V maior.","Com a mesma massa, o dobro do volume significa metade da razão m/V.",{}),
("pr","Verdadeiro ou falso: a pressão no fundo de um recipiente com líquido em repouso depende da profundidade, da massa específica e da gravidade, e não da forma do recipiente.",VF,0,"Teorema de Stevin: p = p₀ + μ·g·h.","Só a altura da coluna de líquido, a massa específica e g entram no cálculo.",{"v":1,"f":"hidro"}),
("pr","Em vasos comunicantes com um mesmo líquido em repouso, o que se observa?",["O líquido atinge o mesmo nível em todos os ramos.","O líquido sobe mais no ramo mais largo.","O líquido sobe mais no ramo mais estreito.","O líquido fica mais alto no ramo mais inclinado."],0,"Pontos na mesma horizontal têm a mesma pressão.","A pressão depende da altura da coluna, não da largura do ramo. Por isso o nível é o mesmo.",{}),
("pr","Qual é a pressão total no fundo do mar a 10 m de profundidade? (p atm = 1,0 × 10⁵ Pa, μ = 1000 kg/m³, g = 10 m/s²)",["2,0 × 10⁵ Pa","1,0 × 10⁵ Pa","1,0 × 10⁶ Pa","1,1 × 10⁵ Pa"],0,"p = p atm + μ·g·h.","p = 10⁵ + 1000 × 10 × 10 = 10⁵ + 10⁵ = 2,0 × 10⁵ Pa.",{"c":1}),
("pr","Um mergulhador desce de 2 m para 6 m de profundidade. A pressão sobre ele:",["Aumenta.","Diminui.","Fica igual.","Fica nula."],0,"A pressão cresce com a profundidade.","Pelo teorema de Stevin, quanto maior a profundidade, maior a pressão.",{}),
("pa","Verdadeiro ou falso: em cidades de grande altitude, a água ferve a uma temperatura menor que ao nível do mar.",VF,0,"Pressão menor, ponto de ebulição menor.","Em altitudes maiores a pressão atmosférica é menor, e a água ferve a uma temperatura mais baixa.",{"v":1}),
("pa","O barômetro é um instrumento usado para medir:",["A pressão atmosférica.","A temperatura do ar.","A umidade do ar.","A velocidade do vento."],0,"O de Torricelli usa mercúrio.","O barômetro mede a pressão atmosférica, como o de mercúrio de Torricelli.",{}),
("pa","Ao puxar o êmbolo de uma seringa com a ponta mergulhada em um líquido, o líquido entra na seringa porque:",["A pressão dentro da seringa diminui e a pressão externa empurra o líquido.","O êmbolo atrai o líquido por magnetismo.","O líquido é mais leve que o ar.","A seringa produz líquido."],0,"Semelhante ao canudo.","Ao puxar o êmbolo, a pressão interna diminui. A pressão atmosférica sobre o líquido o empurra para dentro.",{}),
("pa","Em qual destes lugares a pressão do ar é menor?",["No topo do Everest.","Em Santos, ao nível do mar.","No fundo de uma mina.","Em uma praia."],0,"Menos ar acima, menos pressão.","No alto de uma montanha muito elevada, a coluna de ar acima é pequena e a pressão é a menor das opções.",{}),
("to","O que acontece com a coluna de mercúrio se um pouco de ar entrar no espaço do topo do tubo de Torricelli?",["A coluna diminui.","A coluna aumenta.","Não muda.","O mercúrio some."],0,"O ar passa a exercer pressão sobre o mercúrio por cima.","O ar no topo empurra o mercúrio para baixo, então a altura da coluna diminui.",{"f":"torricelli"}),
("to","Uma pressão de 380 mmHg corresponde a quantas atmosferas?",["0,5 atm","2 atm","3,8 atm","0,38 atm"],0,"1 atm = 760 mmHg.","380 / 760 = 0,5 atm.",{"c":1}),
("to","Verdadeiro ou falso: se o experimento de Torricelli for feito em um local com pressão atmosférica maior, a coluna de mercúrio fica mais alta.",VF,0,"A coluna equilibra a pressão atmosférica.","Maior pressão atmosférica sustenta uma coluna maior de mercúrio.",{"v":1}),
("to","Qual é a pressão, em mmHg, exercida pela coluna de 76 cm de mercúrio do experimento de Torricelli?",["760 mmHg","76 mmHg","7600 mmHg","7,6 mmHg"],0,"Converta cm para mm.","76 cm = 760 mm, então a pressão é 760 mmHg.",{"c":1}),
]
